    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        parts = [int(x) for x in lines[i + 1].split()]
        idx = 0
        for j in range(n):
            if i == j:
                continue
            costs[i][j] = parts[idx]
            idx += 1

    # We need to find a stable matching
    # This is a stable roommate problem variant

    # Assign initial pairing greedily based on sorted costs
    matching = list(range(n))
    used = [False] * n

    for i in range(n):
        if used[i]:
            continue

        # Sort potential partners by best cost for city i
        best_partners = sorted(range(n), key=lambda j: costs[i][j] if not costs[i][j] == 0 and i != j else float('inf'))

        for j in best_partners:
            if j == i:
                continue
            if not used[j]:
                matching[i] = j
                matching[j] = i
                used[i] = True
                used[j] = True
                break

    # Now check for stability - find if there's a blocking pair
    # A blocking pair (i, j) exists if:
    # - i and j are not paired
    # - cost(i, j) < cost(i, current_partner_of_i)
    # - cost(j, i) < cost(j, current_partner_of_j)

    # A more comprehensive approach: try phase III stable roommate
    # with maximum matching and escaping blocking pairs

    # Build the matching more carefully
    # Each city's preference list (sorted by increasing cost)
    prefs = []
    for i in range(n):
        partner_costs = []
        for j in range(n):
            if i != j and costs[i][j] < 10**9 + 7:
                partner_costs.append((costs[i][j], j))
        partner_costs.sort(key=lambda x: x[0])
        prefs.append([j for _, j in partner_costs])

    matching = [-1] * n
    paired = [False] * n

    # Find initial matching
    for i in range(n):
        if paired[i]:
            continue
        for j in prefs[i]:
            if not paired[j]:
                matching[i] = j
                matching[j] = i
                paired[i] = paired[j] = True
                break

    # Check for blocking pairs
    def is_stable(matching, paired, prefs):
        for i in range(n):
            if paired[i]:
                current = matching[i]
                current_cost = costs[i][current] if i != current else float('inf')

                # Check all potential partners with better costs
                for j in prefs[i]:
                    if j == current:
                        continue
                    if not paired[j]:
                        continue
                    if current_cost <= costs[i][j]:
                        continue

                    # Check if j would also prefer i over their current partner
                    current_j = matching[j]
                    current_j_cost = costs[j][current_j] if j != current_j else float('inf')

                    if paired[j] and current_j_cost <= costs[j][i]:
                        continue

                    if current_j_cost > costs[j][i]:
                        return False
        return True

    # If not stable initially, we can't resolve it due to problem constraints
    if n % 2 == 1:
        return "-1\n"

    if not is_stable(matching, paired, prefs):
        return "-1\n"

    # Output result
    result = []
    for i in range(n):
        result.append(str(matching[i] + 1))
        result.append('\n')
    print(''.join(result), end='')

    return ''.join(result)

