def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    # Parse clauses
    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)

    # Map literals to 0..2*m-1
    # Positive x maps to x-1, Negative -x maps to m+x-1
    def to_lit(lit):
        if lit > 0:
            return lit - 1
        else:
            return m + lit - 1

    # Build implication graph
    # For a clause (l1 OR l2 OR ... OR lk), we have implications:
    # ~li -> lj for all i != j in 1..k
    adj = [[] for _ in range(2 * m)]

    for clause in clauses:
        k = len(clause)
        for i in range(k):
            # The negation of literal clause[i]
            not_clause_i = to_lit(-clause[i])
            # For each other literal in the clause, we have: ~clause[i] -> clause[j]
            for j in range(k):
                if i != j:
                    other_lit = to_lit(clause[j])
                    adj[not_clause_i].append(other_lit)

    # Find SCCs using Kosaraju's algorithm
    # First pass: DFS and fill order
    visited = [False] * (2 * m)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(2 * m):
        if not visited[i]:
            dfs1(i)

    # Build reverse graph
    rev_adj = [[] for _ in range(2 * m)]
    for u in range(2 * m):
        for v in adj[u]:
            rev_adj[v].append(u)

    # Second pass: DFS on reverse graph in reverse order
    component = [-1] * (2 * m)
    comp_id = 0

    def dfs2(u, label):
        component[u] = label
        for v in rev_adj[u]:
            if component[v] == -1:
                dfs2(v, label)

    for u in reversed(order):
        if component[u] == -1:
            dfs2(u, comp_id)
            comp_id += 1

    # Check for unsatisfiability
    for x in range(1, m + 1):
        pos = to_lit(x)
        neg = to_lit(-x)
        if component[pos] == component[neg]:
            return "NO"

    # Assign values based on component order (topological sort)
    # Higher component ID means comes later in topological order
    # If variable x has neg > pos, then pos = 1 (x is true)
    # If variable x has pos > neg, then pos = 0 (x is false)

    assignment = [0] * m
    for x in range(1, m + 1):
        pos = to_lit(x)
        neg = to_lit(-x)
        if component[pos] > component[neg]:
            assignment[x - 1] = 1
        else:
            assignment[x - 1] = 0

    result = "YES\n" + "".join(map(str, assignment))
    return result

