def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    if m <= n - 1:
        return ""

    edges = []
    for i in range(1, m + 1):
        a, b, e = map(int, lines[i].split())
        edges.append((a - 1, b - 1, e, i))  # 0-indexed, store original index

    # Sort edges by weight (MST algorithm)
    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_edges = []
    non_mst_indices = set()

    for u, v, e, original_idx in sorted_edges:
        if union(u, v):
            mst_edges.append((u, v, e))
        else:
            non_mst_indices.add(original_idx)

    # Build adjacency list for MST
    adj = [[] for _ in range(n)]
    for u, v, e in mst_edges:
        adj[u].append((v, e))
        adj[v].append((u, e))

    # Precompute depths, parents and max edges for binary lifting
    depth = [0] * n
    up = [[-1] * n for _ in range(20)]  # up[k][u] = 2^k-th parent
    max_path = [[-1] * n for _ in range(20)]  # max_path[k][u] = max edge on path to 2^k-th parent

    # BFS/DFS to compute initial level 0 (parent is itself)
    # Then use it to build tree

    def bfs():
