import sys

def power(a, b, m):
    result = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        b //= 2
        a = (a * a) % m
    return result

def modInverse(n, m):
    return power(n, m - 2, m)

def factorial(n, m):
    res = 1
    for i in range(2, n + 1):
        res = (res * i) % m
    return res

def invFactorial(n, m):
    return modInverse(factorial(n, m), m)

