                    # Down
                    if i + 1 < n:
                        if new_v2 < dp[new_k][i + 1][j]:
                            dp[new_k][i + 1][j] = new_v2
                            from_dir[get_idx(new_k, i + 1, j)] = 'U'  # from up

    # Find best result
    min_zeros = INF
    best_k = -1

