def parse_expression(expr):
    """Parse the expression into list of (sign, coefficient, operation_type)."""
    summands = []
    i = 0
    n = len(expr)

    while i < n:
        # Parse sign (+ or -)
        sign = 1
        if expr[i] == '-':
            sign = -1
            i += 1
            if i < n and expr[i] == '+':
                # This might be ++a, continue parsing
                pass
            elif i < n and expr[i] == '-':
                # Handle consecutive operators
                i += 1
        elif expr[i] == '+':
            i += 1

        if i >= n:
            break

        # Check if next is ++a or has coefficient
        if i + 2 < n and expr[i:i+2] == '++':
            # ++a type
            op = 'pre'
            i += 2
            if i < n and expr[i:i+1] == 'a':
                i += 1
        elif i < n and expr[i].isdigit():
            # Has coefficient
            num_str = ''
            while i < n and expr[i].isdigit():
                num_str += expr[i]
                i += 1
            coef = int(num_str)

            if i < n and expr[i] == '*':
                i += 1  # consume *

            # Get operation
            if i + 2 < n and expr[i:i+2] == 'a++':
                op = 'post'
                i += 3
            elif i + 2 < n and expr[i:i+2] == '++a':
                op = 'pre'
                i += 2
            elif i < n and expr[i] == 'a':
                op = 'post'
                i += 1
            elif i < n and expr[i] == '+':
                op = 'pre'
                i += 1
            continue  # might be anomaly
        else:
            # a++ or ++a without coefficient
            coef = 1

            op = 'post'
            if i + 2 < n and expr[i:i+2] == 'a++':
                i += 3
            elif i + 2 < n and expr[i:i+2] == '++a':
                op = 'pre'
                i += 2
            elif i < n and expr[i] == 'a':
                i += 1
            elif i < n and expr[i] == '+':
                op = 'pre'
                i += 1
            sign = 1  # No sign means positive

        summands.append((sign, coef, op))

    return summands


def calc_value(a, summands, order):
    """Calculate the value given an execution order."""
    current_a = a
    total = 0

    for idx in order:
        sign, coef, op_type = summands[idx]

        if op_type == 'post':
            # a++: use current a, then increment
            total += sign * coef * current_a
            current_a += 1
        else:  # pre: ++a
            # ++a: increment first, then use
            current_a += 1
            total += sign * coef * current_a

    return total


def solution(input_str):
    lines = input_str.strip().split('\n')
    a = int(lines[0])
    expr = lines[1].strip()

    summands = parse_expression(expr)
    n = len(summands)

    if n == 0:
        return str(a)

    # For small number of summands, try all permutations to find maximum
    if n <= 8:
        from itertools import permutations
        max_val = -float('inf')

        for perm in permutations(range(n)):
            val = calc_value(a, summands, list(perm))
            if val > max_val:
                max_val = val

        return str(max_val)
    else:
        # For larger n, use greedy approach
        # Sort by coefficient (positive descending, negative ascending)
        def sort_key(item):
            sign, coef, _ = item
            if sign > 0:
                return -coef  # descending for positive
            else:
                return coef  # ascending for negative

        summands_sorted = sorted(summands, key=sort_key)
        max_val = calc_value(a, summands_sorted, [i for i in range(n)])
        return str(max_val)

