def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    parts = input_str.strip().split()
    n = int(parts[0])
    l = int(parts[1])
    r = int(parts[2])

    if n == 1:
        return str(r - l + 1) + '\n'

    if n == 2:
        return str((r - l + 1) * (r - l)) + '\n'

    # For n >= 26, q^(n-1) >= 2^25 = 33,554,432 > 10^7
    # So no valid progressions exist
    if n > 24:
        return '0\n'

    ans = 0

    # Search for valid (p, q) pairs where gcd(p, q) = 1
    for q in range(2, 500):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        for p in range(2, 500):
            p_pow = p ** (n - 1)
            if p_pow > r:
                break

            # Need coprime for unique progressions
            if gcd(p, q) != 1:
                continue

            if p >= q:
                # Increasing progression
                # min_m: a_1 = m * q^(n-1) >= l, so m >= ceil(l / q^(n-1))
                min_m = max(1, (l + q_pow - 1) // q_pow)
                # max_m: a_n = m * p^(n-1) <= r, stronger since p >= q
                max_m = r // p_pow
            else:
                # Decreasing progression
                # min_m: a_n = m * p^(n-1) >= l
                min_m = max(1, (l + p_pow - 1) // p_pow)
                # max_m: a_1 = m * q^(n-1) <= r
                max_m = r // q_pow

            if min_m <= max_m:
                ans += (max_m - min_m + 1)

    return str(ans) + '\n'

