import sys

def is_prime(num):
    """Check if num is prime"""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def get_unique_prime_factors(n):
    """Get all unique prime factors of n"""
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.append(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors

def is_primitive_root(a, p):
    """Check if a is a primitive root modulo p (where p is prime)"""
    if a <= 1 or a >= p:
        return False
    phi = p - 1
    factors = get_unique_prime_factors(phi)

    for q in factors:
        if pow(a, phi // q, p) == 1:
            return False
    return True

def solution(input_str):
    """
    Find the largest base b (1 < b < x) such that there exists a Rotatable Number
    of length n under base b. This requires n+1 to be prime and b to be a primitive root mod (n+1).
    """
    n, x = map(int, input_str.strip().split())

    p = n + 1

    if not is_prime(p):
        return "-1\n"

    if x <= 2:
        return "-1\n"

    max_b = min(x - 1, p - 1)

    for b in range(max_b, 1, -1):
        if is_primitive_root(b, p):
            return str(b) + "\n"

    return "-1\n"


