def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    pre_edges = []
    pre_adj = set()

    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        pre_edges.append((u, v, w))
        pre_adj.add((min(u, v), max(u, v)))

    # Find all unassigned edges
    unassigned = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if (i, j) not in pre_adj:
                unassigned.append((i, j))

    num_unassigned = len(unassigned)

    # XOR sum of pre-assigned edges
    xor_pre = 0
    for _, _, w in pre_edges:
        xor_pre ^= w

    # Graph of unassigned edges for component detection
    adj_unassigned = [[] for _ in range(n + 1)]
    for u, v in unassigned:
        adj_unassigned[u].append(v)
        adj_unassigned[v].append(u)

    # Find connected components of unassigned edges
    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            comp = []
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                comp.append(u)
                for v in adj_unassigned[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
            components.append(comp)

    num_components = len(components)

    # Map vertex to component
    vertex_to_comp = {}
    for i in range(num_components):
        for v in components[i]:
            vertex_to_comp[v] = i

    # Build MST of components using pre-assigned edges
    parent = list(range(num_components))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        parent[px] = py
        return True

    # Collect edges connecting different components via pre-assigned edges
    comp_edges = []
    for u, v, w in pre_edges:
        cu, cv = vertex_to_comp[u], vertex_to_comp[v]
        if cu != cv:
            comp_edges.append((w, cu, cv))

    # Sort by weight and run Kruskal's
    comp_edges.sort()
    mst_weight = 0
    edges_in_mst = 0

    for w, cu, cv in comp_edges:
        if union(cu, cv):
            mst_weight += w
            edges_in_mst += 1
            if edges_in_mst == num_components - 1:
                break

    # Handle XOR constraint
    if xor_pre == 0:
        return "0" if num_unassigned >= 2 else str(mst_weight)
    else:
        # If XOR != 0, we set one unassigned edge to xor_pre
        # If we have at least 2 unassigned edges, we can choose which one gets the weight
        # If enough unassigned edges exist in components, the X-weight edge won't be needed in MST

        # If the entire graph is connected by unassigned edges, MST weight is 0 (no pre-assigned edges needed)
        if num_components == 1:
            return "0"

        # Otherwise, the MST weight is as computed from pre-assigned edges connecting components
        # The unassigned edge with weight X-XOR won't be used if vertices are in same component
        return str(mst_weight)

