def solve_dp(n_str):
    """
    Uses BFS/memoization to solve the problem for smaller numbers.
    Returns the minimum number of operations to reduce n to 0.
    """
    if n_str == '0':
        return 0

    memo = {}
    visited = set()

    def dp(current):
        if current == 0:
            return 0
        if current in memo:
            return memo[current]
        if current in visited:
            # Shouldn't happen with proper BFS, but safety check
            return float('inf')

        visited.add(current)
        digits = []
        for d in str(current):
            digits.append(int(d))

        min_ops = float('inf')
        for d in digits:
            if d > 0:
                next_val = current - d
                ops = 1 + dp(next_val)
                min_ops = min(min_ops, ops)

        memo[current] = min_ops
        return min_ops

