import math

def solve_competition(s, f, r, v):
    # Solve r*x - r*cos(x) = s to find starting position
    # Use Newton's method
    def f_val(x):
        return r*x - r*math.cos(x) - s

    def df_val(x):
        return r + r*math.sin(x)

    # Initial guess for x where sensor at position s
    x_s = 1.0
    for _ in range(100):
        x_new = x_s - f_val(x_s) / df_val(x_s)
        x_s = x_new

    # Now solve for position f, starting from x_s
    def f_f(x):
        return r*x - r*math.cos(x) - f

    def df_f(x):
        return r + r*math.sin(x)

    x_f = x_s + r * (f - s) / r  # Initial guess
    for _ in range(100):
        x_new = x_f - f_f(x_f) / df_f(x_f)
        x_f = x_new

    # Calculate time based on direct formula
    time = (f - s) / v
    return time

