import functools

@functools.lru_cache(maxsize=None)
def CountDecompositions(n):
    if n <= 0:
        return 0

    # Get all Fibonacci numbers <= n
    fibs = []
    a, b = 1, 2
    while a <= n:
        fibs.append(a)
        a, b = b, a + b

    # dp[i] = number of ways to represent i as sum of distinct Fibonacci numbers from fibs[i:]
    # We work backwards from largest Fibonacci numbers

    memo = {}

    def count_with_fibs(target, fib_idx):
        if target == 0:
            return 1
        if target < 0 or fib_idx >= len(fibs):
            return 0
        if (target, fib_idx) in memo:
            return memo[(target, fib_idx)]

        fib = fibs[fib_idx]
        # Option 1: Don't include fib
        result = count_with_fibs(target, fib_idx + 1)
        # Option 2: Include fib (if it doesn't exceed target)
        if fib <= target:
            result += count_with_fibs(target - fib, fib_idx + 1)

        memo[(target, fib_idx)] = result
        return result

    return count_with_fibs(n, 0)

